    year,
    tSec,
    reason,
    projected,
    cause,
    explanation,
    monsterCount: state.civilization?.chaos?.monsterCount ?? null,
    title: reason === "tenuresExhausted" ? "DYNASTY COMPLETE" : projected ? "FORESEEN EXTINCTION" : "GAME OVER",
